using Microsoft.Data.SqlClient;using QuanLyThueSanTheThao.Data;using QuanLyThueSanTheThao.Helpers;
namespace QuanLyThueSanTheThao.Forms.Customer;
public partial class FrmCustomerVouchers:Form
{
    public FrmCustomerVouchers(){InitializeComponent();Shown+=(_,__)=>LoadData();}
    private void LoadData(){flow.Controls.Clear();var dt=Db.Query(@"SELECT v.MaPhieuGiamGia,v.TenPhieuGiamGia,v.LoaiGiamGia,v.GiaTriGiam,v.MucGiamToiDa,v.DonToiThieu,v.NgayKetThuc,cv.DaSuDung FROM PhieuGiamGiaKhachHang cv JOIN PhieuGiamGia v ON v.PhieuGiamGiaID=cv.PhieuGiamGiaID WHERE cv.KhachHangID=@c ORDER BY cv.DaSuDung,v.NgayKetThuc",new SqlParameter("@c",SessionContext.CustomerId??0));foreach(System.Data.DataRow r in dt.Rows){var used=Convert.ToBoolean(r["DaSuDung"]);var p=new QuanLyThueSanTheThao.Forms.Common.RoundedPanel{Width=360,Height=165,BackColor=Color.White,Margin=new Padding(6),Padding=new Padding(16),Radius=14,BorderColor=AppTheme.Border};var name=new Label{Text=Convert.ToString(r["TenPhieuGiamGia"]),Font=new Font("Segoe UI Semibold",14F,FontStyle.Bold),ForeColor=used?Color.Gray:AppTheme.AccentDark,AutoSize=true,Location=new Point(16,16)};var code=new Label{Text="Mã: "+Convert.ToString(r["MaPhieuGiamGia"]),AutoSize=true,Location=new Point(16,52)};var value=Convert.ToString(r["LoaiGiamGia"])=="Percent"?$"Giảm {Convert.ToDecimal(r["GiaTriGiam"]):0.#}%":$"Giảm {Convert.ToDecimal(r["GiaTriGiam"]):N0}đ";var info=new Label{Text=$"{value}\nĐơn tối thiểu {Convert.ToDecimal(r["DonToiThieu"]):N0}đ\nHSD: {Convert.ToDateTime(r["NgayKetThuc"]):dd/MM/yyyy}"+(used?"\nĐÃ SỬ DỤNG":""),AutoSize=true,ForeColor=used?Color.Gray:AppTheme.Text,Location=new Point(16,78)};p.Controls.AddRange(new Control[]{name,code,info});flow.Controls.Add(p);}}
}
